import subprocess
import csv
import os

def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError('commands file path does not exist')
    if not os.path.exists(output_dir_path):
        os.makedirs(output_dir_path)
    with open(commands_file_path, 'r') as file:
        reader = csv.reader(file)
        for idx, row in enumerate(reader, 1):
            if row:
                command = row[0]
                result = subprocess.run(command, shell=True, capture_output=True, text=True)
                output = result.stdout + result.stderr
                if result.returncode != 0:
                    output += f'\nError executing command, exited with code {result.returncode}'
                output_file_path = os.path.join(output_dir_path, f'command_{idx}_output.txt')
                with open(output_file_path, 'w') as output_file:
                    output_file.write(output)

