from scipy import stats

def task_func(original):
    numbers = []
    for tup in original:
        for item in tup:
            if isinstance(item, (int, float)):
                numbers.append(item)
    arr = np.array(numbers)
    if arr.size == 0:
        stats_dict = {
            'mean': np.nan,
            'std': np.nan,
            'min': np.nan,
            'max': np.nan
        }
    else:
        stats_dict = {
            'mean': np.mean(arr),
            'std': np.std(arr),
            'min': np.min(arr),
            'max': np.max(arr)
        }
    fig, ax = plt.subplots()
    ax.hist(arr, density=True, alpha=0.6, bins='auto', label='Data')
    if arr.size > 0:
        xmin, xmax = ax.get_xlim()
        x = np.linspace(xmin, xmax, 100)
        p = stats.norm.pdf(x, stats_dict['mean'], stats_dict['std'])
        ax.plot(x, p, 'k', linewidth=2, label='PDF')
    ax.legend()
    ax.set_title('Histogram with PDF')
    return arr, stats_dict, ax

