import time

def task_func(file_list):
    exit_codes = [None] * len(file_list)

    def run_file(index, file_path):
        try:
            process = subprocess.run([file_path], capture_output=True, text=True)
            exit_codes[index] = process.returncode
        except Exception as e:
            exit_codes[index] = -1

    threads = []
    for i, file_path in enumerate(file_list):
        thread = threading.Thread(target=run_file, args=(i, file_path))
        threads.append(thread)
        thread.start()
        time.sleep(0.01)  # Small delay to improve concurrency

    for thread in threads:
        thread.join()

    return exit_codes

