import subprocess
import threading

def task_func(file_list):
    exit_codes = [None] * len(file_list)

    def run_file(index, file_path):
        try:
            process = subprocess.Popen([file_path])
            process.wait()
            exit_codes[index] = process.returncode
        except OSError:
            # Handle cases where the process fails to start (e.g., file not found, permission denied)
            exit_codes[index] = -200
        except Exception as e:
            # Handle other unexpected errors
            exit_codes[index] = -1

    threads = []
    for i, file_path in enumerate(file_list):
        thread = threading.Thread(target=run_file, args=(i, file_path))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return exit_codes

import os
import shutil
import glob

def task_func(src_dir, dest_dir, ext):
    if not os.path.exists(src_dir):
        return []
    if not os.path.exists(dest_dir):
        os.makedirs(dest_dir)
    moved_files = []
    pattern = os.path.join(src_dir, f'*{ext}')
    for file_path in glob.glob(pattern):
        if os.path.isfile(file_path):
            try:
                shutil.move(file_path, dest_dir)
                moved_files.append(file_path)
            except Exception:
                continue
    return moved_files

