import json
import re
import pandas as pd

def task_func(json_str):
    """
    Load a JSON string into a dictionary, process it by doubling numerical values and converting string numbers,
    and create a Pandas DataFrame. Returns an empty DataFrame if input is empty or invalid.
    Ensures numeric columns are converted to float type where possible.

    Parameters:
    json_str (str): The JSON string to convert.

    Returns:
    DataFrame: A pandas DataFrame created from the processed JSON string, or empty DataFrame if input is invalid.

    Requirements:
    - json
    - re
    - pandas

    Example:
    >>> json_str = '{"Name": ["Tom", "Nick", "John"], "Age": [20, 21, 19], "Score": [85.5, 90.0, 78.3]}'
    >>> df = task_func(json_str)
    >>> print(df)
       Name   Age  Score
    0   Tom  40.0  171.0
    1  Nick  42.0  180.0
    2  John  38.0  156.6
    """
    if not json_str or not json_str.strip():
        return pd.DataFrame()

    try:
        data_dict = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()

    if not data_dict or data_dict in ([], {}, None):
        return pd.DataFrame()

    def process_value(value):
        if isinstance(value, dict):
            return {k: process_value(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [process_value(item) for item in value]
        elif isinstance(value, str):
            if re.match(r'^[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?$', value.strip()):
                try:
                    num = float(value)
                    return num * 2
                except (ValueError, TypeError):
                    return value
            return value
        elif isinstance(value, (int, float)):
            return value * 2
        else:
            return value

    try:
        processed_dict = process_value(data_dict)
        df = pd.DataFrame(processed_dict)

        # Convert numeric columns to float
        for col in df.columns:
            if pd.api.types.is_numeric_dtype(df[col]):
                df[col] = df[col].astype(float)

        return df
    except (ValueError, TypeError):
        return pd.DataFrame()

