import requests
from lxml import html
import pandas as pd
import sqlite3
import urllib.parse

def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        if webpage_url.startswith('file://'):
            file_path = urllib.parse.unquote(webpage_url[7:])
            try:
                with open(file_path, 'r', encoding='utf-8') as file:
                    content = file.read()
            except Exception as e:
                raise requests.RequestException("there is any issue accessing the URL.") from e
            tree = html.fromstring(content)
        else:
            try:
                response = requests.get(webpage_url)
                response.raise_for_status()
            except Exception as e:
                raise requests.RequestException("there is any issue accessing the URL.") from e
            tree = html.fromstring(response.content)

        table_elements = tree.xpath('//table')
        if not table_elements:
            return 0

        table_element = table_elements[0]
        table_html = html.tostring(table_element)
        df = pd.read_html(table_html)[0]

        if df.empty:
            return 0

        row_count = len(df)

        try:
            conn = sqlite3.connect(database_name)
            df.to_sql('my_table', conn, if_exists='replace', index=False)
            conn.close()
        except Exception as e:
            raise sqlite3.DatabaseError("there are some error during connecting or writing to db.") from e

        return row_count
    except (requests.RequestException, sqlite3.DatabaseError):
        raise
    except Exception:
        return 0

