                except (UnicodeDecodeError, LookupError) as e:
                    raise ValueError('Incorrect encoding provided.') from e
            return text
    except Exception:
        pass  # OCR failed, proceed to comment fallback

    # Second attempt: Comment field extraction
    try:
        img = Image.open(filename)
        comment = img.info.get('comment')
        if comment is None:
            return ""

        if isinstance(comment, str):
            return comment

        if isinstance(comment, bytes):
            if from_encoding:
                try:
                    decoded_comment = comment.decode(from_encoding)
                except (UnicodeDecodeError, LookupError) as e:
                    raise ValueError('Incorrect encoding provided.') from e

                if to_encoding:
                    try:
                        decoded_comment = decoded_comment.encode(to_encoding).decode(to_encoding)
                    except (UnicodeDecodeError, LookupError) as e:
                        raise ValueError('Incorrect encoding provided.') from e

                return decoded_comment
            else:
                return ""  # No from_encoding provided for bytes comment
    except Exception:
        pass  # Comment processing failed

    return ""  # Both OCR and comment processing failed

