import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"The script {script_path} does not exist.")

    max_cpu = 0.0
    max_memory = 0

    try:
        proc = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        psutil_proc = psutil.Process(proc.pid)

        start_time = time.time()
        while proc.poll() is None and (time.time() - start_time) < timeout:
            try:
                cpu_usage = psutil_proc.cpu_percent(interval=0.1)
                memory_usage = psutil_proc.memory_info().rss

                if cpu_usage > max_cpu:
                    max_cpu = cpu_usage
                if memory_usage > max_memory:
                    max_memory = memory_usage
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                break

        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=1)
            except subprocess.TimeoutExpired:
                proc.kill()
    except Exception as e:
        raise RuntimeError(f"Error executing script: {str(e)}")

    return {'CPU Usage': max_cpu, 'Memory Usage': max_memory}

