import json
import pandas as pd
import numpy as np

def task_func(input_file="data.json"):
    # Read the JSON file
    with open(input_file, 'r') as f:
        data = json.load(f)

    # Initialize a dictionary to collect numeric values for each key
    key_values = {}

    # Iterate through each dictionary in the list
    for d in data:
        for key, value in d.items():
            # Check if the value is numeric (int or float)
            if isinstance(value, (int, float)):
                if key not in key_values:
                    key_values[key] = []
                key_values[key].append(value)

    # Calculate the mean for each key, using np.nan if no numeric values
    means = {}
    for key, values in key_values.items():
        if values:
            means[key] = np.mean(values)
        else:
            means[key] = np.nan

    # Create DataFrame with keys as index and a single column 'mean'
    result_df = pd.DataFrame.from_dict(means, orient='index', columns=['mean'])

    return result_df

