import re
import os
from pathlib import Path
import csv

def task_func(directory: str, pattern: str = r'^(.*?)-\d+\.csv$') -> list:
    renamed_files = []
    dir_path = Path(directory)

    # Check if directory exists
    if not dir_path.exists():
        raise FileNotFoundError(f"The directory '{directory}' does not exist.")

    # Check if we have read and write permissions for the directory
    if not os.access(directory, os.R_OK | os.W_OK):
        raise PermissionError(f"Permission denied: cannot read or write in '{directory}'.")

    for file_path in dir_path.iterdir():
        if file_path.is_file():
            match = re.fullmatch(pattern, file_path.name)
            if match:
                new_name = match.group(1) + '.csv'
                new_path = dir_path / new_name
                if not new_path.exists():
                    file_path.rename(new_path)
                    renamed_files.append((file_path.name, new_name))
    return renamed_files

